import unicodedata

MAX_CHARACTERS = 10000
CONTROL_NAMES = {
    "\t": "CHARACTER TABULATION",
    "\n": "LINE FEED",
    "\r": "CARRIAGE RETURN",
}

def escape_character(character, category):
    if character == "\t":
        return "\\t"
    if character == "\n":
        return "\\n"
    if character == "\r":
        return "\\r"
    if category[0] in "CMZ":
        code = ord(character)
        return f"\\u{code:04X}" if code <= 0xFFFF else f"\\U{code:08X}"
    return character

def process(data):
    text = data["selection"]
    if not text:
        raise ValueError("Text is empty")
    if len(text) > MAX_CHARACTERS:
        raise ValueError(
            "Text exceeds 10,000 Unicode code points"
        )

    lines = []
    for character in text:
        code = ord(character)
        category = unicodedata.category(character)
        display = escape_character(character, category)
        name = CONTROL_NAMES.get(
            character, unicodedata.name(character, "<unnamed>")
        )
        lines.append(f"U+{code:04X}\t{display}\t{name}\t{category}")
    return "\n".join(lines)
